SELECT o.id, c.name
FROM orders o
INNER JOIN customers c ON c.id = o.customer_id;

SELECT *,
       ROW_NUMBER() OVER (PARTITION BY team ORDER BY score DESC) AS rn
FROM players;

SELECT * FROM (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY team ORDER BY score DESC) AS rn
  FROM players
) t
WHERE rn <= 3;

WITH recent AS (
  SELECT * FROM orders WHERE created_at > now() - interval '30 days'
)
SELECT customer_id, COUNT(*) FROM recent GROUP BY customer_id;

INSERT INTO users (name, email) VALUES ('Ada', 'ada@example.com');
UPDATE users SET active = false WHERE last_login < now() - interval '1 year';
DELETE FROM sessions WHERE expires_at < now();

INSERT INTO settings (key, value)
VALUES ('theme', 'dark')
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

CREATE TABLE orders (
  id          BIGSERIAL PRIMARY KEY,
  customer_id BIGINT NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  total       NUMERIC(10, 2) NOT NULL CHECK (total >= 0),
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_orders_customer ON orders (customer_id);
CREATE UNIQUE INDEX idx_users_email ON users (email);
CREATE INDEX idx_orders_open ON orders (created_at) WHERE status = 'open';

SELECT date_trunc('month', created_at) AS month, COUNT(*)
FROM orders
GROUP BY 1
ORDER BY 1;

SELECT now() - interval '7 days', EXTRACT(year FROM now());

BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;      -- or ROLLBACK;

SELECT data->>'name' AS name, data->'address'->>'city' AS city
FROM profiles
WHERE data @> '{"active": true}';

CREATE USER app WITH PASSWORD 'change-me';
CREATE DATABASE appdb OWNER app;
GRANT ALL PRIVILEGES ON DATABASE appdb TO app;
